INSERT INTO _fleet_sync_reports(item_id,report_seq,outcome_kind,outcome_acceptance,refusal_kind,refusal_code,refusal_failure,refusal_size_field,refusal_digest,refusal_item_id,outcome_cancel_item_id,outcome_too_late_at) VALUES(?1,CAST(?2 AS INTEGER),json_extract(?3,'$.outcome.kind'),CASE WHEN json_type(?3,'$.outcome.value.acceptance') IS NOT NULL THEN ?3 -> '$.outcome.value.acceptance' END,json_extract(?3,'$.outcome.value.reason.kind'),json_extract(?3,'$.outcome.value.reason.value.code'),json_extract(?3,'$.outcome.value.reason.value.kind'),json_extract(?3,'$.outcome.value.reason.value.field'),CASE WHEN json_extract(?3,'$.outcome.value.reason.kind')='itemConflict' THEN json_extract(?3,'$.outcome.value.reason.value.existing') ELSE json_extract(?3,'$.outcome.value.reason.value.existing.digest') END,json_extract(?3,'$.outcome.value.reason.value.existing.item'),json_extract(?3,'$.outcome.value.cancel'),json_extract(?3,'$.outcome.value.at')) ON CONFLICT(item_id) DO UPDATE SET report_seq=excluded.report_seq,outcome_kind=excluded.outcome_kind,outcome_acceptance=excluded.outcome_acceptance,refusal_kind=excluded.refusal_kind,refusal_code=excluded.refusal_code,refusal_failure=excluded.refusal_failure,refusal_size_field=excluded.refusal_size_field,refusal_digest=excluded.refusal_digest,refusal_item_id=excluded.refusal_item_id,outcome_cancel_item_id=excluded.outcome_cancel_item_id,outcome_too_late_at=excluded.outcome_too_late_at,updated_at=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) WHERE excluded.report_seq>_fleet_sync_reports.report_seq;
